<script setup>import {ref,onMounted} from 'vue';import http from '../api/http';const list=ref([]);const orderId=ref('');const load=async()=>list.value=(await http.get('/purchase/list')).data.data;const apply=async()=>{await http.post('/purchase/apply',{deviceCode:'DEV-X',hospitalId:21,hospitalName:'第一医院',operator:'hosp1'});load()};const approve=async()=>{await http.post('/purchase/approve',{orderId:orderId.value,operator:'sup1'});load()};const receive=async()=>{await http.post('/purchase/receive',{orderId:orderId.value,operator:'hosp1'});load()};onMounted(load)</script>
<template><div><h3>采购</h3><button @click='apply'>发起采购</button><input v-model='orderId' placeholder='orderId'/><button @click='approve'>审批</button><button @click='receive'>收货</button><pre>{{list}}</pre></div></template>
